insert into public.permissions(code,name_ar,module) values('inventory.approve','اعتماد حركة مخزون','inventory'),('expenses.approve','اعتماد مصروف','expenses'),('treasury.create','إنشاء خزنة أو بنك','finance'),('treasury.transfer','تحويل مالي داخلي','finance') on conflict(code) do nothing;
create or replace function public.create_cash_register(p_name text,p_opening_balance numeric default 0,p_limit numeric default null) returns public.cash_registers language plpgsql security definer set search_path=public as $$declare r public.cash_registers;begin if auth.uid() is null or not public.current_user_has_permission('treasury.create') then raise exception 'غير مصرح بإضافة خزنة';end if;if nullif(btrim(p_name),'') is null then raise exception 'اسم الخزنة مطلوب';end if;insert into public.cash_registers(name,opening_balance,limit_amount,responsible_id) values(btrim(p_name),greatest(p_opening_balance,0),p_limit,auth.uid()) returning * into r;return r;end;$$;
create or replace function public.create_bank(p_name text,p_account_name text default null,p_masked_account text default null,p_opening_balance numeric default 0) returns public.banks language plpgsql security definer set search_path=public as $$declare b public.banks;begin if auth.uid() is null or not public.current_user_has_permission('treasury.create') then raise exception 'غير مصرح بإضافة بنك';end if;if nullif(btrim(p_name),'') is null then raise exception 'اسم البنك مطلوب';end if;insert into public.banks(name,account_name,masked_account,opening_balance,responsible_id) values(btrim(p_name),p_account_name,p_masked_account,greatest(p_opening_balance,0),auth.uid()) returning * into b;return b;end;$$;
create or replace function public.create_expense_draft(p_category text,p_amount numeric,p_payment_method text,p_cash_register_id uuid default null,p_bank_id uuid default null,p_payee text default null,p_department text default null,p_description text default null) returns public.expenses language plpgsql security definer set search_path=public as $$declare e public.expenses;begin if auth.uid() is null or not public.current_user_has_permission('expenses.create') then raise exception 'غير مصرح بإضافة مصروف';end if;if nullif(btrim(p_category),'') is null or p_amount<=0 then raise exception 'أدخل نوع المصروف والمبلغ';end if;if p_payment_method='cash' and p_cash_register_id is null then raise exception 'اختر الخزنة';end if;if p_payment_method='bank' and p_bank_id is null then raise exception 'اختر البنك';end if;insert into public.expenses(category,amount,payment_method,cash_register_id,bank_id,payee,department,description,created_by) values(btrim(p_category),p_amount,p_payment_method,p_cash_register_id,p_bank_id,p_payee,p_department,p_description,auth.uid()) returning * into e;return e;end;$$;
create or replace function public.approve_expense(p_expense_id uuid) returns public.expenses language plpgsql security definer set search_path=public as $$declare e public.expenses;begin if auth.uid() is null or not public.current_user_has_permission('expenses.approve') then raise exception 'غير مصرح باعتماد المصروف';end if;select * into e from public.expenses where id=p_expense_id for update;if e.id is null then raise exception 'المصروف غير موجود';end if;if e.status<>'draft' then raise exception 'المصروف اعتمد أو ألغي سابقًا';end if;if e.payment_method='cash' then insert into public.cash_transactions(cash_register_id,direction,transaction_type,amount,related_type,related_id,created_by,notes) values(e.cash_register_id,'out','expense',e.amount,'expense',e.id,auth.uid(),e.category);end if;if e.payment_method='bank' then insert into public.bank_transactions(bank_id,direction,transaction_type,amount,related_type,related_id,created_by,notes) values(e.bank_id,'out','expense',e.amount,'expense',e.id,auth.uid(),e.category);end if;update public.expenses set status='approved',approved_by=auth.uid(),approved_at=now() where id=e.id returning * into e;return e;end;$$;
grant execute on function public.create_cash_register(text,numeric,numeric) to authenticated;grant execute on function public.create_bank(text,text,text,numeric) to authenticated;grant execute on function public.create_expense_draft(text,numeric,text,uuid,uuid,text,text,text) to authenticated;grant execute on function public.approve_expense(uuid) to authenticated;
